package com.example.library.service;

import com.example.library.model.*;
import jakarta.annotation.PostConstruct;
import org.springframework.stereotype.Service;
import java.sql.*;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.*;

@Service
public class LibraryService {
    private static final String URL = "jdbc:sqlite:library.db";
    private Connection connect() throws SQLException { return DriverManager.getConnection(URL); }

    @PostConstruct public void init() {
        try (Connection c = connect(); Statement s = c.createStatement()) {
            s.executeUpdate("CREATE TABLE IF NOT EXISTS books(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,author TEXT NOT NULL,category TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Available')");
            s.executeUpdate("CREATE TABLE IF NOT EXISTS members(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,type TEXT NOT NULL,email TEXT NOT NULL UNIQUE)");
            s.executeUpdate("CREATE TABLE IF NOT EXISTS issues(id INTEGER PRIMARY KEY AUTOINCREMENT,book_id INTEGER NOT NULL,member_id INTEGER NOT NULL,issue_date TEXT NOT NULL,due_date TEXT NOT NULL,return_date TEXT,fine REAL NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'Issued',FOREIGN KEY(book_id) REFERENCES books(id),FOREIGN KEY(member_id) REFERENCES members(id))");
            try (ResultSet r=s.executeQuery("SELECT COUNT(*) FROM books")) { if(r.next() && r.getInt(1)==0) {
                s.executeUpdate("INSERT INTO books(title,author,category,status) VALUES ('Atomic Habits','James Clear','Personal Growth','Available'),('The Alchemist','Paulo Coelho','Fiction','Available'),('Clean Code','Robert C. Martin','Technology','Available'),('Wings of Fire','A. P. J. Abdul Kalam','Biography','Available'),('Ikigai','Héctor García','Wellness','Available'),('The Pragmatic Programmer','Andrew Hunt','Technology','Available')");
                s.executeUpdate("INSERT INTO members(name,type,email) VALUES ('Aarav Sharma','Student','aarav@example.com'),('Mira Patel','Student','mira@example.com'),('Dr. Neha Rao','Teacher','neha.rao@example.com')");
            }}
        } catch (SQLException e) { throw new IllegalStateException("Could not initialize SQLite database",e); }
    }
    public List<Book> books(String q) { List<Book> out=new ArrayList<>(); String sql="SELECT * FROM books WHERE lower(title) LIKE ? OR lower(author) LIKE ? ORDER BY id DESC"; try(Connection c=connect();PreparedStatement p=c.prepareStatement(sql)){String x="%"+(q==null?"":q.toLowerCase())+"%";p.setString(1,x);p.setString(2,x);try(ResultSet r=p.executeQuery()){while(r.next())out.add(new Book(r.getLong("id"),r.getString("title"),r.getString("author"),r.getString("category"),r.getString("status")));}}catch(SQLException e){throw fail(e);}return out;}
    public Book addBook(String title,String author,String category){ if(blank(title)||blank(author))throw new IllegalArgumentException("Title and author are required.");try(Connection c=connect();PreparedStatement p=c.prepareStatement("INSERT INTO books(title,author,category) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,title.trim());p.setString(2,author.trim());p.setString(3,blank(category)?"General":category.trim());p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){return new Book(r.next()?r.getLong(1):0,title.trim(),author.trim(),blank(category)?"General":category.trim(),"Available");}}catch(SQLException e){throw fail(e);}}
    public void deleteBook(long id){try(Connection c=connect()){try(PreparedStatement p=c.prepareStatement("SELECT status FROM books WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Book was not found.");if(!"Available".equals(r.getString(1)))throw new IllegalArgumentException("An issued book cannot be deleted.");}}try(PreparedStatement p=c.prepareStatement("DELETE FROM books WHERE id=?")){p.setLong(1,id);p.executeUpdate();}}catch(SQLException e){throw fail(e);}}
    public List<Member> members(){List<Member> out=new ArrayList<>();try(Connection c=connect();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT * FROM members ORDER BY id DESC")){while(r.next())out.add(new Member(r.getLong("id"),r.getString("name"),r.getString("type"),r.getString("email")));}catch(SQLException e){throw fail(e);}return out;}
    public Member addMember(String name,String type,String email){if(blank(name)||blank(email)||!email.contains("@"))throw new IllegalArgumentException("Enter a name and a valid email address.");if(!List.of("Student","Teacher").contains(type))throw new IllegalArgumentException("Choose Student or Teacher.");try(Connection c=connect();PreparedStatement p=c.prepareStatement("INSERT INTO members(name,type,email) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,name.trim());p.setString(2,type);p.setString(3,email.trim());p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){return new Member(r.next()?r.getLong(1):0,name.trim(),type,email.trim());}}catch(SQLException e){if(e.getMessage()!=null&&e.getMessage().contains("UNIQUE"))throw new IllegalArgumentException("That email is already registered.");throw fail(e);}}
    public List<IssueRecord> issues(){List<IssueRecord> out=new ArrayList<>();String sql="SELECT i.*,b.title,m.name FROM issues i JOIN books b ON b.id=i.book_id JOIN members m ON m.id=i.member_id ORDER BY i.id DESC";try(Connection c=connect();Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){while(r.next())out.add(new IssueRecord(r.getLong("id"),r.getLong("book_id"),r.getString("title"),r.getLong("member_id"),r.getString("name"),r.getString("issue_date"),r.getString("due_date"),r.getString("return_date"),r.getDouble("fine"),r.getString("status")));}catch(SQLException e){throw fail(e);}return out;}
    public IssueRecord issue(long bookId,long memberId){try(Connection c=connect()){c.setAutoCommit(false);try{String title,status;try(PreparedStatement p=c.prepareStatement("SELECT title,status FROM books WHERE id=?")){p.setLong(1,bookId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Book ID was not found.");title=r.getString(1);status=r.getString(2);}}if(!"Available".equals(status))throw new IllegalArgumentException("This book is already issued.");String name,type;try(PreparedStatement p=c.prepareStatement("SELECT name,type FROM members WHERE id=?")){p.setLong(1,memberId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Member ID was not found.");name=r.getString(1);type=r.getString(2);}}int limit=type.equals("Student")?3:5;try(PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM issues WHERE member_id=? AND status='Issued'")){p.setLong(1,memberId);try(ResultSet r=p.executeQuery()){r.next();if(r.getInt(1)>=limit)throw new IllegalArgumentException(type+" borrowing limit is "+limit+" books.");}}LocalDate today=LocalDate.now(),due=today.plusDays(14);try(PreparedStatement p=c.prepareStatement("INSERT INTO issues(book_id,member_id,issue_date,due_date) VALUES(?,?,?,?)")){p.setLong(1,bookId);p.setLong(2,memberId);p.setString(3,today.toString());p.setString(4,due.toString());p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE books SET status='Issued' WHERE id=?")){p.setLong(1,bookId);p.executeUpdate();}c.commit();return new IssueRecord(0,bookId,title,memberId,name,today.toString(),due.toString(),null,0,"Issued");}catch(RuntimeException|SQLException e){c.rollback();if(e instanceof RuntimeException re)throw re;throw fail((SQLException)e);}finally{c.setAutoCommit(true);}}catch(SQLException e){throw fail(e);}}
    public IssueRecord returnBook(long issueId){try(Connection c=connect()){c.setAutoCommit(false);try{long bookId,memberId;String due,status;try(PreparedStatement p=c.prepareStatement("SELECT book_id,member_id,due_date,status FROM issues WHERE id=?")){p.setLong(1,issueId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Issue record was not found.");bookId=r.getLong(1);memberId=r.getLong(2);due=r.getString(3);status=r.getString(4);}}if(!"Issued".equals(status))throw new IllegalArgumentException("This book has already been returned.");String type;try(PreparedStatement p=c.prepareStatement("SELECT type FROM members WHERE id=?")){p.setLong(1,memberId);try(ResultSet r=p.executeQuery()){r.next();type=r.getString(1);}}LocalDate today=LocalDate.now();long late=Math.max(0,ChronoUnit.DAYS.between(LocalDate.parse(due),today));double fine=late*(type.equals("Student")?2:1);try(PreparedStatement p=c.prepareStatement("UPDATE issues SET return_date=?,fine=?,status='Returned' WHERE id=?")){p.setString(1,today.toString());p.setDouble(2,fine);p.setLong(3,issueId);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE books SET status='Available' WHERE id=?")){p.setLong(1,bookId);p.executeUpdate();}c.commit();return new IssueRecord(issueId,bookId,"",memberId,"","",due,today.toString(),fine,"Returned");}catch(RuntimeException|SQLException e){c.rollback();if(e instanceof RuntimeException re)throw re;throw fail((SQLException)e);}finally{c.setAutoCommit(true);}}catch(SQLException e){throw fail(e);}}
    private boolean blank(String s){return s==null||s.trim().isEmpty();} private RuntimeException fail(SQLException e){return new IllegalStateException(e.getMessage(),e);}
}
